<script lang="ts">import PostCard from '$lib/PostCard.svelte';let {data}=$props();</script><svelte:head><title>Blogs — Page {data.page} | Sagar Panda</title><link rel="canonical" href={'https://sagarpanda.com/blogs/page/'+data.page+'/'} /></svelte:head><main id="main-content" class="shell page-shell"><section class="section"><div class="command">$ ls ~/blogs --page {data.page}</div><h1>Blogs <span class="muted">/ Page {data.page}</span></h1><div class="post-list">{#each data.posts as post}<PostCard {post}/>{/each}</div><div class="pagination"><a href={data.page===2?'/blogs/':'/blogs/page/'+(data.page-1)+'/'}>← Newer posts</a>{#if data.page<data.totalPages}<a href={'/blogs/page/'+(data.page+1)+'/'}>Older posts →</a>{/if}</div></section></main>